        .setFontFamily("Arial").setFontSize(10).setBold(true).setSpacingBefore(6).setSpacingAfter(4);
    body.appendParagraph("Teacher Initials (Initial Grading): ________   Date: ____________   Resubmission Due Date: ____________\nStudent Signature (Revisions Complete): ________________________   Revised Score: _____ / 50   Initials: _____")
        .setFontFamily("Arial").setFontSize(9).setBold(false);

    doc.saveAndClose();

    // Share Doc & Export PDF
    const driveFile = DriveApp.getFileById(doc.getId());
    driveFile.setSharing(DriveApp.Access.ANYONE_WITH_LINK, DriveApp.Permission.VIEW);

    const pdfBlob = driveFile.getAs(MimeType.PDF);
    pdfBlob.setName(item.fileName + ".pdf");
    const pdfFile = DriveApp.createFile(pdfBlob);
    pdfFile.setSharing(DriveApp.Access.ANYONE_WITH_LINK, DriveApp.Permission.VIEW);

    Logger.log(item.fileName + " (Google Doc): " + driveFile.getUrl());
    Logger.log(item.fileName + " (PDF): " + pdfFile.getUrl());
